type Circle = { kind: "circle"; radius: number };
type Square = { kind: "square"; side: number };
type Shape = Circle | Square;

function area(shape: Shape): number {
  switch (shape.kind) {
    case "circle": return Math.PI * shape.radius ** 2;
    case "square": return shape.side ** 2;
    default: { const _: never = shape; return _; }
  }
}

type ApiSuccess<T> = { ok: true; data: T };
type ApiFailure = { ok: false; error: string; code: number };
type ApiResult<T> = ApiSuccess<T> | ApiFailure;

function handle<T>(result: ApiResult<T>): T {
  if (!result.ok) throw new Error(`[${result.code}] ${result.error}`);
  return result.data;
}

type AddTodo = { type: "ADD_TODO"; text: string };
type ToggleTodo = { type: "TOGGLE_TODO"; id: string };
type TodoAction = AddTodo | ToggleTodo;
